void run6(int64_t B, int64_t m, const double* x0, const double* c, double* out1, double* outm){
  init_all();
  int64_t b = 0;
  {
    int64_t g8 = (B / 8) * 8;
    int64_t rem = B - g8;
    for(; b < g8; b += 8)
      bgroup_6(m, x0 + b*432, c + b*432, out1 + b*432, outm + b*432, 8);
    if(rem >= 5){
      bgroup_6(m, x0 + b*432, c + b*432, out1 + b*432, outm + b*432, rem);
      b = B;
    }
  }
  for(; b<B; ++b){
    const double* xb = x0 + b*432;
    const double* cb = c  + b*432;
    if(m < 1){
    for(long x=0; x<6; ++x)
      deint(xb + x*72, SR6 + x*40, SI6 + x*40, 36);
      for(long x=0; x<6; ++x) inter(SR6 + x*40, SI6 + x*40, outm + b*432 + x*72, 36);
      
      pz_6(SR6, SI6);
      py_6(SR6, SI6);
      PXI6(SR6, SI6, cb);
      for(long x=0; x<6; ++x) inter(SR6 + x*40, SI6 + x*40, out1 + b*432 + x*72, 36);
      continue;
    }
    // iteration 1: fused deinterleave of x0
    pzf_6(xb, SR6, SI6);
    
      py_6(SR6, SI6);
    if(m == 1){
      PXF6(SR6, SI6, cb, out1 + b*432);
      if(outm != out1) memcpy(outm + b*432, out1 + b*432, 432*sizeof(double));
      continue;
    }
    if(m >= 6){
      for(long x=0; x<6; ++x)
        deint(cb + x*72, CR6 + x*40, CI6 + x*40, 36);
      PXS6(SR6, SI6, CR6, CI6);
      for(long x=0; x<6; ++x) inter(SR6 + x*40, SI6 + x*40, out1 + b*432 + x*72, 36);
      for(int64_t it=1; it<m-1; ++it){
        
      pz_6(SR6, SI6);
      py_6(SR6, SI6);
        PXS6(SR6, SI6, CR6, CI6);
      }
    } else {
      PXD6(SR6, SI6, cb, out1 + b*432);
      for(int64_t it=1; it<m-1; ++it){
        
      pz_6(SR6, SI6);
      py_6(SR6, SI6);
        PXI6(SR6, SI6, cb);
      }
    }
    
      pz_6(SR6, SI6);
      py_6(SR6, SI6);
    PXF6(SR6, SI6, cb, outm + b*432);
  }
}
