#define SR8 (ARENA + 12288)
#define SI8 (ARENA + 13440)
#define CR8 (ARENA + 14592)
#define CI8 (ARENA + 15744)
#define SBR8 (ARENA + 17408)
#define SBI8 (ARENA + 22144)
#define CBR8 (ARENA + 26880)
#define CBI8 (ARENA + 31616)


static void bgroup_8(int64_t m, const double* xb, const double* cb, double* o1, double* om, long nv){
  bin_8(xb, SBR8, SBI8, nv);
  bin_8(cb, CBR8, CBI8, nv);
  if(m < 1){
    bout_8(SBR8, SBI8, om, nv);
    bzy_8(SBR8, SBI8); bpx_8(SBR8, SBI8, CBR8, CBI8);
    bout_8(SBR8, SBI8, o1, nv);
    return;
  }
  for(int64_t it=0; it<m; ++it){
    bzy_8(SBR8, SBI8); bpx_8(SBR8, SBI8, CBR8, CBI8);
    if(it == 0) bout_8(SBR8, SBI8, o1, nv);
  }
  if(m != 1 || om != o1) bout_8(SBR8, SBI8, om, nv);
}
void run8(int64_t B, int64_t m, const double* x0, const double* c, double* out1, double* outm){
  init_all();
  int64_t b = 0;
  {
    int64_t g8 = (B / 8) * 8;
    int64_t rem = B - g8;
    for(; b < g8; b += 8)
      bgroup_8(m, x0 + b*1024, c + b*1024, out1 + b*1024, outm + b*1024, 8);
    if(rem >= 7){
      bgroup_8(m, x0 + b*1024, c + b*1024, out1 + b*1024, outm + b*1024, rem);
      b = B;
    }
  }
  for(; b<B; ++b){
    const double* xb = x0 + b*1024;
    const double* cb = c  + b*1024;
    if(m < 1){
    for(long x=0; x<8; ++x)
      deint(xb + x*128, SR8 + x*64, SI8 + x*64, 64);
      for(long x=0; x<8; ++x) inter(SR8 + x*64, SI8 + x*64, outm + b*1024 + x*128, 64);
      
      pz_8(SR8, SI8);
      py_8(SR8, SI8);
      PXI8(SR8, SI8, cb);
      for(long x=0; x<8; ++x) inter(SR8 + x*64, SI8 + x*64, out1 + b*1024 + x*128, 64);
      continue;
    }
    // iteration 1: fused deinterleave of x0
    pzf_8(xb, SR8, SI8);
    
      py_8(SR8, SI8);
    if(m == 1){
      PXF8(SR8, SI8, cb, out1 + b*1024);
      if(outm != out1) memcpy(outm + b*1024, out1 + b*1024, 1024*sizeof(double));
      continue;
    }
    if(m >= 6){
      for(long x=0; x<8; ++x)
        deint(cb + x*128, CR8 + x*64, CI8 + x*64, 64);
      PXS8(SR8, SI8, CR8, CI8);
      for(long x=0; x<8; ++x) inter(SR8 + x*64, SI8 + x*64, out1 + b*1024 + x*128, 64);
      for(int64_t it=1; it<m-1; ++it){
        
      pz_8(SR8, SI8);
      py_8(SR8, SI8);
        PXS8(SR8, SI8, CR8, CI8);
      }
    } else {
      PXD8(SR8, SI8, cb, out1 + b*1024);
      for(int64_t it=1; it<m-1; ++it){
        
      pz_8(SR8, SI8);
      py_8(SR8, SI8);
        PXI8(SR8, SI8, cb);
      }
    }
    
      pz_8(SR8, SI8);
      py_8(SR8, SI8);
    PXF8(SR8, SI8, cb, outm + b*1024);
  }
}
static const double* DBGC8;
void dtr8(long reps){ for(long r=0;r<reps;++r){ pz_8(SR8, SI8); py_8(SR8, SI8); PXS8(SR8, SI8, CR8, CI8); } }
void dpz8(long reps){ for(long r=0;r<reps;++r){ pz_8(SR8, SI8); } }
void dpy8(long reps){ for(long r=0;r<reps;++r){ py_8(SR8, SI8); } }
void dpx8(long reps){ for(long r=0;r<reps;++r){ PXS8(SR8, SI8, CR8, CI8); } }
void dseed8(const double* x0, const double* c){
  init_all();
  DBGC8 = c;
  for(long x=0; x<8; ++x){
    deint(x0 + x*128, SR8 + x*64, SI8 + x*64, 64);
    deint(c + x*128, CR8 + x*64, CI8 + x*64, 64);
  }
}
