static void bin_17(const double* restrict src, double* restrict re, double* restrict im, long nv){
 for(long pb=0; pb<615; ++pb){
  long p0 = pb*8;
  V rr[8], ii[8];
  __mmask8 q1 = 0xFF, q2 = 0xFF; if(pb == 614){ q1 = 0x3; q2 = 0x0; }
  for(long v=0; v<8; ++v){
    V a, b;
    if(v < nv){
      a = _mm512_maskz_loadu_pd(q1, src + v*9826 + p0*2);
      b = _mm512_maskz_loadu_pd(q2, src + v*9826 + p0*2 + 8);
    } else { a = _mm512_setzero_pd(); b = a; }
    rr[v] = _mm512_permutex2var_pd(a, XRE, b);
    ii[v] = _mm512_permutex2var_pd(a, XIM, b);
  }
  TR8(rr[0],rr[1],rr[2],rr[3],rr[4],rr[5],rr[6],rr[7]);
  TR8(ii[0],ii[1],ii[2],ii[3],ii[4],ii[5],ii[6],ii[7]);
  for(long t=0; t<8; ++t){ STU(re + (p0+t)*8, rr[t]); STU(im + (p0+t)*8, ii[t]); }
 }
}
static void bout_17(const double* restrict re, const double* restrict im, double* restrict dst, long nv){
 for(long pb=0; pb<615; ++pb){
  long p0 = pb*8;
  V rr[8], ii[8];
  __mmask8 q1 = 0xFF, q2 = 0xFF; if(pb == 614){ q1 = 0x3; q2 = 0x0; }
  for(long t=0; t<8; ++t){ rr[t] = LDU(re + (p0+t)*8); ii[t] = LDU(im + (p0+t)*8); }
  TR8(rr[0],rr[1],rr[2],rr[3],rr[4],rr[5],rr[6],rr[7]);
  TR8(ii[0],ii[1],ii[2],ii[3],ii[4],ii[5],ii[6],ii[7]);
  for(long v=0; v<nv; ++v){
    MST(dst + v*9826 + p0*2,     q1, _mm512_permutex2var_pd(rr[v], XLO, ii[v]));
    MST(dst + v*9826 + p0*2 + 8, q2, _mm512_permutex2var_pd(rr[v], XHI, ii[v]));
  }
 }
}
