#define SBI17 (ARENA + 185984)
#define CBR17 (ARENA + 225536)
#define CBI17 (ARENA + 265088)


static void bgroup_17(int64_t m, const double* xb, const double* cb, double* o1, double* om, long nv){
  bin_17(xb, SBR17, SBI17, nv);
  bin_17(cb, CBR17, CBI17, nv);
  if(m < 1){
    bout_17(SBR17, SBI17, om, nv);
    bzy_17(SBR17, SBI17); bpx_17(SBR17, SBI17, CBR17, CBI17);
    bout_17(SBR17, SBI17, o1, nv);
    return;
  }
  for(int64_t it=0; it<m; ++it){
    bzy_17(SBR17, SBI17); bpx_17(SBR17, SBI17, CBR17, CBI17);
    if(it == 0) bout_17(SBR17, SBI17, o1, nv);
  }
  if(m != 1 || om != o1) bout_17(SBR17, SBI17, om, nv);
}
void run17(int64_t B, int64_t m, const double* x0, const double* c, double* out1, double* outm){
  init_all();
  int64_t b = 0;
  {
    int64_t g8 = (B / 8) * 8;
    int64_t rem = B - g8;
    for(; b < g8; b += 8)
      bgroup_17(m, x0 + b*9826, c + b*9826, out1 + b*9826, outm + b*9826, 8);
    if(rem >= 6){
      bgroup_17(m, x0 + b*9826, c + b*9826, out1 + b*9826, outm + b*9826, rem);
      b = B;
    }
  }
  for(; b<B; ++b){
    const double* xb = x0 + b*9826;
    const double* cb = c  + b*9826;
    if(m < 1){
    for(long x=0; x<17; ++x)
      deint(xb + x*578, SR17 + x*296, SI17 + x*296, 289);
      for(long x=0; x<17; ++x) inter(SR17 + x*296, SI17 + x*296, outm + b*9826 + x*578, 289);
      
      pz_17(SR17, SI17);
      py_17(SR17, SI17);
      PXI17(SR17, SI17, cb);
      for(long x=0; x<17; ++x) inter(SR17 + x*296, SI17 + x*296, out1 + b*9826 + x*578, 289);
      continue;
    }
    // iteration 1: fused deinterleave of x0
    pzf_17(xb, SR17, SI17);
    
      py_17(SR17, SI17);
    if(m == 1){
      PXF17(SR17, SI17, cb, out1 + b*9826);
      if(outm != out1) memcpy(outm + b*9826, out1 + b*9826, 9826*sizeof(double));
      continue;
    }
    if(m >= 6){
      for(long x=0; x<17; ++x)
        deint(cb + x*578, CR17 + x*296, CI17 + x*296, 289);
      PXS17(SR17, SI17, CR17, CI17);
      for(long x=0; x<17; ++x) inter(SR17 + x*296, SI17 + x*296, out1 + b*9826 + x*578, 289);
      for(int64_t it=1; it<m-1; ++it){
        
      pz_17(SR17, SI17);
      py_17(SR17, SI17);
        PXS17(SR17, SI17, CR17, CI17);
      }
    } else {
      PXD17(SR17, SI17, cb, out1 + b*9826);
      for(int64_t it=1; it<m-1; ++it){
        
      pz_17(SR17, SI17);
      py_17(SR17, SI17);
        PXI17(SR17, SI17, cb);
      }
    }
    
      pz_17(SR17, SI17);
      py_17(SR17, SI17);
    PXF17(SR17, SI17, cb, outm + b*9826);
  }
}
