#define CI23 (ARENA + 347008)
#define SBR23 (ARENA + 361472)
#define SBI23 (ARENA + 459392)
#define CBR23 (ARENA + 557312)
#define CBI23 (ARENA + 655232)


static void bgroup_23(int64_t m, const double* xb, const double* cb, double* o1, double* om, long nv){
  bin_23(xb, SBR23, SBI23, nv);
  bin_23(cb, CBR23, CBI23, nv);
  if(m < 1){
    bout_23(SBR23, SBI23, om, nv);
    bzy_23(SBR23, SBI23); bpx_23(SBR23, SBI23, CBR23, CBI23);
    bout_23(SBR23, SBI23, o1, nv);
    return;
  }
  for(int64_t it=0; it<m; ++it){
    bzy_23(SBR23, SBI23); bpx_23(SBR23, SBI23, CBR23, CBI23);
    if(it == 0) bout_23(SBR23, SBI23, o1, nv);
  }
  if(m != 1 || om != o1) bout_23(SBR23, SBI23, om, nv);
}
void run23(int64_t B, int64_t m, const double* x0, const double* c, double* out1, double* outm){
  init_all();
  int64_t b = 0;
  {
    int64_t g8 = (B / 8) * 8;
    int64_t rem = B - g8;
    for(; b < g8; b += 8)
      bgroup_23(m, x0 + b*24334, c + b*24334, out1 + b*24334, outm + b*24334, 8);
    if(rem >= 8){
      bgroup_23(m, x0 + b*24334, c + b*24334, out1 + b*24334, outm + b*24334, rem);
      b = B;
    }
  }
  for(; b<B; ++b){
    const double* xb = x0 + b*24334;
    const double* cb = c  + b*24334;
    if(m < 1){
    for(long x=0; x<23; ++x)
      deint(xb + x*1058, SR23 + x*568, SI23 + x*568, 529);
      for(long x=0; x<23; ++x) inter(SR23 + x*568, SI23 + x*568, outm + b*24334 + x*1058, 529);
      
      pz_23(SR23, SI23);
      py_23(SR23, SI23);
      PXI23(SR23, SI23, cb);
      for(long x=0; x<23; ++x) inter(SR23 + x*568, SI23 + x*568, out1 + b*24334 + x*1058, 529);
      continue;
    }
    // iteration 1: fused deinterleave of x0
    pzf_23(xb, SR23, SI23);
    
      py_23(SR23, SI23);
    if(m == 1){
      PXF23(SR23, SI23, cb, out1 + b*24334);
      if(outm != out1) memcpy(outm + b*24334, out1 + b*24334, 24334*sizeof(double));
      continue;
    }
    if(m >= 6){
      for(long x=0; x<23; ++x)
        deint(cb + x*1058, CR23 + x*568, CI23 + x*568, 529);
      PXS23(SR23, SI23, CR23, CI23);
      for(long x=0; x<23; ++x) inter(SR23 + x*568, SI23 + x*568, out1 + b*24334 + x*1058, 529);
      for(int64_t it=1; it<m-1; ++it){
        
      pz_23(SR23, SI23);
      py_23(SR23, SI23);
        PXS23(SR23, SI23, CR23, CI23);
      }
    } else {
      PXD23(SR23, SI23, cb, out1 + b*24334);
      for(int64_t it=1; it<m-1; ++it){
        
      pz_23(SR23, SI23);
      py_23(SR23, SI23);
        PXI23(SR23, SI23, cb);
      }
    }
    
      pz_23(SR23, SI23);
      py_23(SR23, SI23);
    PXF23(SR23, SI23, cb, outm + b*24334);
  }
}
