#define SR64 (ARENA + 1323008)
#define SI64 (ARENA + 1588864)
#define CR64 (ARENA + 1854720)
#define CI64 (ARENA + 2120576)


void run64(int64_t B, int64_t m, const double* x0, const double* c, double* out1, double* outm){
  init_all();
  int64_t b = 0;

  for(; b<B; ++b){
    const double* xb = x0 + b*524288;
    const double* cb = c  + b*524288;
    if(m < 1){
    for(long x=0; x<64; ++x)
      deint(xb + x*8192, SR64 + x*4136, SI64 + x*4136, 4096);
      for(long x=0; x<64; ++x) inter(SR64 + x*4136, SI64 + x*4136, outm + b*524288 + x*8192, 4096);
      
      for(long x=0; x<64; ++x){
        pz_64(SR64 + x*4136, SI64 + x*4136);
        py_64(SR64 + x*4136, SI64 + x*4136);
      }
      PXI64(SR64, SI64, cb);
      for(long x=0; x<64; ++x) inter(SR64 + x*4136, SI64 + x*4136, out1 + b*524288 + x*8192, 4096);
      continue;
    }
    // iteration 1: fused deinterleave of x0
    for(long x=0; x<64; ++x){
      pzf_64(xb + x*8192, SR64 + x*4136, SI64 + x*4136);
      py_64(SR64 + x*4136, SI64 + x*4136);
    }
    if(m == 1){
      PXF64(SR64, SI64, cb, out1 + b*524288);
      if(outm != out1) memcpy(outm + b*524288, out1 + b*524288, 524288*sizeof(double));
      continue;
    }
    if(m >= 32){
      for(long x=0; x<64; ++x)
        deint(cb + x*8192, CR64 + x*4136, CI64 + x*4136, 4096);
      PXS64(SR64, SI64, CR64, CI64);
      for(long x=0; x<64; ++x) inter(SR64 + x*4136, SI64 + x*4136, out1 + b*524288 + x*8192, 4096);
      for(int64_t it=1; it<m-1; ++it){
        
      for(long x=0; x<64; ++x){
        pz_64(SR64 + x*4136, SI64 + x*4136);
        py_64(SR64 + x*4136, SI64 + x*4136);
      }
        PXS64(SR64, SI64, CR64, CI64);
      }
    } else {
      PXD64(SR64, SI64, cb, out1 + b*524288);
      for(int64_t it=1; it<m-1; ++it){
        
      for(long x=0; x<64; ++x){
        pz_64(SR64 + x*4136, SI64 + x*4136);
        py_64(SR64 + x*4136, SI64 + x*4136);
      }
        PXI64(SR64, SI64, cb);
      }
    }
    
      for(long x=0; x<64; ++x){
        pz_64(SR64 + x*4136, SI64 + x*4136);
        py_64(SR64 + x*4136, SI64 + x*4136);
      }
    PXF64(SR64, SI64, cb, outm + b*524288);
  }
}
static const double* DBGC64;
void dtr64(long reps){ for(long r=0;r<reps;++r){ for(long x=0;x<64;++x){ pz_64(SR64 + x*4136, SI64 + x*4136); py_64(SR64 + x*4136, SI64 + x*4136);} PXS64(SR64, SI64, CR64, CI64); } }
void dpz64(long reps){ for(long r=0;r<reps;++r){ for(long x=0;x<64;++x) pz_64(SR64 + x*4136, SI64 + x*4136); } }
void dpy64(long reps){ for(long r=0;r<reps;++r){ for(long x=0;x<64;++x) py_64(SR64 + x*4136, SI64 + x*4136); } }
void dpx64(long reps){ for(long r=0;r<reps;++r){ PXS64(SR64, SI64, CR64, CI64); } }
void dseed64(const double* x0, const double* c){
  init_all();
  DBGC64 = c;
  for(long x=0; x<64; ++x){
    deint(x0 + x*8192, SR64 + x*4136, SI64 + x*4136, 4096);
    deint(c + x*8192, CR64 + x*4136, CI64 + x*4136, 4096);
  }
}
